SELECT DISTINCT md.chembl_id AS molecule_chembl_id, cs.canonical_smiles FROM molecule_dictionary md JOIN activities act ON md.molregno = act.molregno JOIN assays a ON act.assay_id = a.assay_id JOIN target_dictionary td ON a.tid = td.tid JOIN compound_structures cs ON md.molregno = cs.molregno WHERE a.assay_organism = 'Homo sapiens' AND td.chembl_id = 'CHEMBL1827' ORDER BY md.chembl_id, cs.canonical_smiles
